import logo from './logo.svg';
import './App.css';

function App() {
  return (
    <div className="min-h-screen bg-gradient-to-r from-blue-500 to-purple-600 flex items-center justify-center">
      <div className="bg-white p-10 rounded-2xl shadow-2xl text-center max-w-md">
        <img src={logo} className="h-24 w-24 mx-auto animate-spin" alt="logo" />
        <h1 className="text-4xl font-bold text-gray-800 mt-4">
          React + Tailwind CSS
        </h1>
        <p className="text-gray-600 mt-2 text-lg">
          🚀 It's working perfectly!
        </p>
        <button className="mt-6 bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-6 rounded-full transition duration-300 transform hover:scale-105">
          Click Me
        </button>
      </div>
    </div>
  );
}

export default App;
